using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.Collections.Generic;
// Standard Windows ICO packaging. A separate code-drawn miniature omits the
// long wordmark at 16-48 px; larger entries use the generated full artwork.
static class BuildIcon {
 static GraphicsPath Round(float x,float y,float w,float h,float r){var p=new GraphicsPath();p.AddArc(x,y,r,r,180,90);p.AddArc(x+w-r,y,r,r,270,90);p.AddArc(x+w-r,y+h-r,r,r,0,90);p.AddArc(x,y+h-r,r,r,90,90);p.CloseFigure();return p;}
 static void Mini(Graphics g){g.ScaleTransform(4,4);using(var shape=Round(1,1,62,62,13))using(var dark=new SolidBrush(Color.FromArgb(12,15,17)))using(var green=new Pen(Color.FromArgb(0,225,80),2)){g.FillPath(dark,shape);g.DrawPath(green,shape);}using(var chassis=Round(6,15,52,35,5))using(var fill=new SolidBrush(Color.FromArgb(40,47,50)))using(var edge=new Pen(Color.Silver,1)){g.FillPath(fill,chassis);g.DrawPath(edge,chassis);}g.FillRectangle(Brushes.Black,43,18,12,29);using(var edge=new Pen(Color.FromArgb(92,104,106),1))for(int y=21;y<45;y+=4)g.DrawLine(edge,45,y,53,y);g.FillRectangle(Brushes.Black,10,19,28,11);g.FillRectangle(Brushes.LimeGreen,12,21,24,6);using(var green=new Pen(Color.LimeGreen,1.1F))for(int x=13;x<=37;x+=8)for(int y=35;y<=44;y+=9){g.DrawEllipse(green,x-2,y-2,4,4);g.FillEllipse(Brushes.Silver,x-1,y-1,2,2);}}
 static int Main(string[] args){var blobs=new List<byte[]>();int[] sizes={16,24,32,48,64,128,256};using(var art=Image.FromFile(args[0]))foreach(int n in sizes){using(var bitmap=new Bitmap(n,n,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;if(n<=48){using(var big=new Bitmap(256,256)){using(var high=Graphics.FromImage(big)){high.SmoothingMode=SmoothingMode.AntiAlias;Mini(high);}g.DrawImage(big,0,0,n,n);}}else g.DrawImage(art,0,0,n,n);}using(var buffer=new MemoryStream()){bitmap.Save(buffer,ImageFormat.Png);blobs.Add(buffer.ToArray());}}}using(var output=new BinaryWriter(File.Create(args[1]))){output.Write((ushort)0);output.Write((ushort)1);output.Write((ushort)sizes.Length);int at=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){output.Write((byte)(sizes[i]==256?0:sizes[i]));output.Write((byte)(sizes[i]==256?0:sizes[i]));output.Write((byte)0);output.Write((byte)0);output.Write((ushort)1);output.Write((ushort)32);output.Write(blobs[i].Length);output.Write(at);at+=blobs[i].Length;}foreach(var b in blobs)output.Write(b);}return 0;}
}
